def need(value,reason):
    if not value:raise RuntimeError(reason)


def load_helper(name,source):
    module=types.ModuleType(name);module.__file__=name+'.py'
    exec(compile(source,module.__file__,'exec'),module.__dict__)
    return module


helpers=json.loads(zlib.decompress(base64.b64decode(HELPERS)))
maintenance=load_helper('maintenance',helpers['maintenance'])
workflow=load_helper('workflow',helpers['workflow'])
measure=load_helper('measure',helpers['measure'])
plans=json.loads(zlib.decompress(base64.b64decode(PLANS)))


def read_bytes(path,limit=1024*1024):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(fd,'rb') as stream:
        info=os.fstat(stream.fileno())
        need(stat.S_ISREG(info.st_mode) and 0<=info.st_size<=limit,'Unexpected bounded regular file: '+str(path))
        value=stream.read(limit+1);need(len(value)<=limit,'Input too large');return value


def read_json(path):return json.loads(read_bytes(path))


def owned_dir(path,mode):
    if not path.exists() and not path.is_symlink():
        path.mkdir(mode=mode);path.chmod(mode)
    info=path.lstat()
    need(stat.S_ISDIR(info.st_mode) and info.st_uid==0 and stat.S_IMODE(info.st_mode)==mode
         and path.resolve(strict=True)==path,'Root staging directory differs: '+str(path))


def put(path,value,shared=False):
    data=(json.dumps(value,indent=2)+'\n').encode()
    temporary=path.with_name(path.name+'.'+uuid.uuid4().hex+'.next')
    fd=os.open(temporary,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as stream:
        stream.write(data);stream.flush()
        if shared:os.fchmod(stream.fileno(),0o644)
        os.fsync(stream.fileno())
    os.replace(temporary,path)
    fd=os.open(path.parent,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(fd)
    finally:os.close(fd)


def stage_file(path,data,mode=0o644):
    if path.exists() or path.is_symlink():
        info=path.lstat()
        need(info.st_uid==0 and stat.S_ISREG(info.st_mode) and stat.S_IMODE(info.st_mode)==mode
             and read_bytes(path,max(len(data),1))==data,'Staged file differs; preserved: '+str(path))
        return
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
    with os.fdopen(fd,'wb') as stream:
        os.fchmod(stream.fileno(),mode);stream.write(data);stream.flush();os.fsync(stream.fileno())


def command(args,timeout=30,owner=False,check=True):
    kwargs={'user':1204,'group':1205,'extra_groups':[],'umask':0o077} if owner else {}
    result=subprocess.run(args,capture_output=True,text=True,timeout=timeout,env=ENV,**kwargs)
    if check:need(result.returncode==0,'Command failed: '+str(args[:3])+' '+result.stderr[-1800:])
    return result


def unit(name):
    keys=['LoadState','ActiveState','SubState','MainPID','Job']
    result=command([maintenance.tool('systemctl'),'show',name,*['--property='+key for key in keys]],check=False)
    values=dict(line.split('=',1) for line in result.stdout.splitlines() if '=' in line)
    need(all(key in values for key in keys),'Cannot inspect exact experiment unit: '+name)
    need(values['Job'] in ('','0'),'Experiment unit has a pending job')
    need(result.returncode==0 or values['LoadState']=='not-found','Unit query failed')
    return values


class Operations:
    def __init__(self,node,state):
        self.node,self.state,self.plan=node,state,plans[node]
        self.work=BASE/node
        self.code=BASE/('code-'+PACKAGE_SHA[:12])
        self.prep=Path(self.plan['workDirectory'])
        self.sdk_unit='aenv-hpmem-v2-'+node+'-sdk.service'
        self.view_unit='aenv-hpmem-v2-'+node+'-view.service'
        self.owner_config=BASE/'configs'/(node+'-sdk.json')
        self.view_config=self.work/'view-config.json'
        self.release_file=BASE/'receipts'/(node+'-local.json')
        maintenance.configure(self.plan['maintenance'])

    def save(self,value):put(self.work/'workflow.json',value)

    def python(self,module,*args):
        return ['/usr/bin/python3','-I','-B','-c',BOOTSTRAP,str(self.code),module,*map(str,args)]

    def stage_sources(self):
        raw=zlib.decompress(base64.b64decode(PACKAGE,validate=True))
        need(hashlib.sha256(raw).hexdigest()==PACKAGE_SHA,'Embedded package differs')
        modules=json.loads(raw)
        owned_dir(self.code,0o755);owned_dir(self.code/'aenv_ub_provider',0o755)
        for name,source in modules.items():
            need(Path(name).name==name and name.endswith('.py'),'Invalid embedded module name')
            stage_file(self.code/'aenv_ub_provider'/name,source.encode())
        adapter=read_bytes(Path(self.plan['adapterFile']),16*MIB)
        need(hashlib.sha256(adapter).hexdigest()==ADAPTER_SHA,'Retained adapter changed')
        stage_file(self.code/'libaenv-ub.so',adapter)

    def validate_prepared(self):
        import grp
        self.validate_sdk_library()
        need(workflow.digest(read_json(self.prep/'prepared.json'))==self.plan['preparedSemanticSha256'],
             'Preparation receipt identity changed')
        need(hashlib.sha256(read_bytes(Path(self.plan['maintenance']['candidateFile']),8*MIB)).hexdigest()==CANDIDATE_SHA,
             'Candidate missing/different; stage the exact existing binary before maintenance')
        need(measure.file_digest(self.plan['baselineFile'],8*MIB)==PAYLOAD_SHA,'Dedicated baseline payload missing/different')
        if self.node=='node-a':
            need(measure.file_digest(self.prep/'host-dax-test.ext4',64*MIB)==IMAGE_SHA,'Prepared container changed')
        need(grp.getgrnam('ubsmd').gr_gid==984,'Existing SDK supplemental group differs')
        for name in ('/run/matrix','/run/matrix/memory','/run/matrix/memory/MxmAgentIpcServer'):
            path=Path(name);info=path.stat()
            need(path.resolve(strict=True)==path and info.st_uid==984 and info.st_gid==984,
                 'Existing SDK IPC identity differs: '+name+' uid/gid='+str((info.st_uid,info.st_gid)))
        for name in (self.sdk_unit,self.view_unit):
            need(unit(name)['LoadState']=='not-found','Existing experiment unit preserved')
        need(not (self.prep/'provider').exists(),'Existing SDK provider state preserved')

    def validate_sdk_library(self):
        path=Path('/usr/lib64/libubsm_sdk.so').resolve(strict=True);info=path.stat()
        need(stat.S_ISREG(info.st_mode) and (info.st_uid,info.st_gid)==(984,984)
             and stat.S_IMODE(info.st_mode)==0o554 and info.st_size==1249536,
             'Existing SDK library attributes differ from the verified 984:984/0554/1249536-byte installation')
        need(measure.file_digest(path,info.st_size)==SDK_SHA,'Existing SDK library bytes changed')

    def activate_module(self):
        self.stage_sources()
        before=list(sys.argv);output=io.StringIO()
        try:
            sys.argv=['maintenance','activate','--approval',APPROVAL]
            with contextlib.redirect_stdout(output):rc=maintenance.main()
        finally:
            sys.argv=before
            (self.work/'maintenance-activate.log').write_text(output.getvalue())
        need(rc==0,'Module activation did not complete; retain recovery journal')
        journal=read_json(maintenance.STAGE/'journal.json')
        need(journal['phase']=='candidate_loaded_ubse_active','Candidate phase differs')
        process=journal['currentProcess']
        try:self.state['engineSchema']=measure.engine_schema(maintenance.tool('rpm'),process['pid'],process['ticks'])
        except RuntimeError as error:self.state['engineSchema']={'attested':False,'reason':str(error)}
        self.save(self.state)  # Attest executable before taking the no-UB baseline.
        return {'bootId':journal['bootId'],'candidateSha256':journal['candidateSha256'],
                'candidateSrcversion':journal['candidateSrcversion'],'ubse':journal['currentProcess'],
                'referenceCount':journal.get('observedReferenceCount'),'taint':journal.get('taintAfter')}

    def check_candidate(self):
        journal=read_json(maintenance.STAGE/'journal.json')
        need(journal['candidateSrcversion']==CANDIDATE_SRC,'Candidate compiled identity differs')
        # A's allocation may already have placed regions on B. Empty-region
        # checks belong to module switching, not joining an existing object.
        need(maintenance.read('/sys/module/obmm/initstate')=='live'
             and maintenance.read('/sys/module/obmm/srcversion')==CANDIDATE_SRC,'Candidate is not live')
        params={item.name:maintenance.read(item) for item in Path('/sys/module/obmm/parameters').iterdir()}
        need(params=={**maintenance.PARAMS,'pmem_ro_enable':'Y'},'Candidate parameters changed')
        status=maintenance.service()
        need(status['ActiveState']=='active' and maintenance.process(int(status['MainPID']))==journal['currentProcess'],
             'UBSE identity changed after maintenance')

    def activation_preflight(self):
        self.validate_prepared()
        maintenance.Local({}).check_old()

    def baseline(self):
        path=self.plan['baselineFile']
        source=None
        if self.node=='node-a':source=measure.evict_dedicated(self.prep/'host-dax-test.ext4',64*MIB,IMAGE_SHA)
        process=read_json(maintenance.STAGE/'journal.json')['currentProcess']
        processes={'ubse':{'pid':process['pid'],'ticks':process['ticks']}}
        cold=measure.evict_dedicated(path,8*MIB,PAYLOAD_SHA)
        before=measure.sample(processes)
        need(measure.file_digest(path,8*MIB)==PAYLOAD_SHA,'Baseline payload changed')
        warm=measure.residency(path,8*MIB)
        after=measure.sample(processes)
        released=measure.evict_dedicated(path,8*MIB,PAYLOAD_SHA)
        result={'coldFile':cold,'warmFile':warm,'afterAdvice':released,'before':before,'after':after,
                'preparationContainerAfterAdvice':source,
                'method':'same dedicated 8MiB payload; per-file advice only; no global cache drop'}
        put(self.work/'baseline.json',result)
        return result

    def start_unit(self,name,module,args,owner):
        need(unit(name)['LoadState']=='not-found','Refuse to replace an existing unit')
        properties=['Type=exec','Restart=no','NoNewPrivileges=yes','UMask=0077','KillMode=control-group',
                    'WorkingDirectory='+self.plan['workspace'],'TimeoutStopSec=90s',
                    'LimitNOFILE=4096','LimitCORE=0','LimitMEMLOCK='+str(384*MIB),
                    'MemoryMax='+str(1280*MIB)]
        properties += ['CapabilityBoundingSet=','AmbientCapabilities='] if owner else [
            'CapabilityBoundingSet=CAP_SYS_ADMIN CAP_SETUID CAP_DAC_READ_SEARCH CAP_DAC_OVERRIDE']
        if owner:properties+=['SupplementaryGroups=ubsmd','RestrictSUIDSGID=yes']
        logfile=self.prep/('sdk.log' if owner else 'view.log')
        properties += ['StandardOutput=append:'+str(logfile),'StandardError=append:'+str(logfile)]
        argv=[maintenance.tool('systemd-run'),'--unit='+name,'--quiet']
        if owner:argv+=['--uid=1204','--gid=1205']
        argv += ['--property='+value for value in properties]
        argv += ['--',*self.python(module,*args)]
        command(argv)

    def wait_ready(self,name,path,phase):
        deadline=time.monotonic()+300
        while time.monotonic()<deadline:
            status=unit(name)
            need(status['ActiveState'] not in ('failed','inactive'),'Owned helper exited; inspect its preserved journal/log')
            if path.exists():
                record=read_json(path)
                state=record.get('phase',record.get('state'))
                if state==phase:
                    pid=int(status['MainPID']);need(pid>0,'No main process')
                    ticks=measure.process_identity(pid)
                    return record,{'pid':pid,'ticks':ticks}
                need(state not in ('unresolved_preserved','stopped_preserve_resources','retirement_stopped_preserve_resources'),
                     'Owned helper stopped; preserve resources and use explicit retirement')
            time.sleep(1)
        raise TimeoutError('Owned helper readiness timeout; no retry or forced cleanup')

    def start_sdk(self,publication):
        self.validate_sdk_library()
        config={'version':1,'mode':'pmem','role':'publish' if self.node=='node-a' else 'import',
                'workDir':str(self.prep/'provider'),'adapter':str(self.code/'libaenv-ub.so'),
                'adapterSha256':'sha256:'+ADAPTER_SHA,'region':'default',
                'logicalBudgetBytes':64*MIB,'maxCoverageBytes':256*MIB,
                'hostPmemReleaseReceipt':str(self.release_file)}
        if self.node=='node-a':
            config.update(readers=['host-pmem-b-v1'],catalog=str(self.prep/'catalog.json'),
                          hostPmemReaderEpochs={'host-pmem-b-v1':self.state['peerEvidence']['epoch']})
        else:
            manifest_path=BASE/'configs'/(self.node+'-publisher.json');put(manifest_path,publication,shared=True)
            config.update(readerId='host-pmem-b-v1',manifest=str(manifest_path))
        put(self.owner_config,config,shared=True)
        self.start_unit(self.sdk_unit,'aenv_ub_provider',['serve',self.owner_config,'--run'],True)
        journal,process=self.wait_ready(self.sdk_unit,self.prep/'provider/owner.json','serving')
        observed=read_json(self.prep/'provider/replicas.json')
        if publication is not None:need(observed==publication,'Imported SDK publication differs')
        need(observed['mode']=='pmem' and observed['readers']==['host-pmem-b-v1'] and len(observed['replicas'])==1,
             'Unexpected SDK publication shape')
        replica=observed['replicas'][0]
        need(replica['identity']['sha256']=='sha256:'+IMAGE_SHA and replica['identity']['bytes']==64*MIB,
             'Published image identity differs')
        return {'publication':observed,'process':process,'ownerJournal':journal}

    def start_view(self,owner):
        source={**owner['publication']['replicas'][0]['identity'],'socket':str(self.prep/'provider/data.sock')}
        config={'version':1,'workDir':str(self.work/'view'),'source':source,
                'ownerUid':1204,'ownerPid':owner['process']['pid'],'ownerStartTicks':owner['process']['ticks'],
                'publication':owner['publication'],'releaseReceipt':str(self.release_file),
                'testFile':{'name':'payload.bin','bytes':8*MIB,'sha256':PAYLOAD_SHA},
                'kernelRelease':KERNEL,'moduleSrcversion':CANDIDATE_SRC}
        put(self.view_config,config)
        result=command(self.python('aenv_ub_provider.host_pmem_cli','plan','--config',self.view_config))
        pin=json.loads(result.stdout)['configSha256'];self.state['viewConfigSha256']=pin;self.save(self.state)
        self.state['viewLaunchAttempted']=True;self.save(self.state)
        self.start_unit(self.view_unit,'aenv_ub_provider.host_pmem_cli',[
            'serve','--config',self.view_config,'--expected-config-sha256',pin,
            '--approval','CREATE_READONLY_HOST_PMEM_VIEW'],False)
        journal,process=self.wait_ready(self.view_unit,self.work/'view/host-pmem-session.json','local_read_verified')
        return {'process':process,'journal':journal}

    def measure(self):
        # Preparation and source hashing may have warmed A's image. Advise only
        # this owned, exact synthetic source away; retain measured leftovers.
        ordinary={'baseline':measure.evict_dedicated(self.plan['baselineFile'],8*MIB,PAYLOAD_SHA)}
        if self.node=='node-a':ordinary['container']=measure.evict_dedicated(self.prep/'host-dax-test.ext4',64*MIB,IMAGE_SHA)
        reply=self.verify_again()
        proc={'sdk':self.state['owner']['process'],'view':self.state['view']['process']}
        root_journal=read_json(self.work/'view/host-pmem-session.json')
        ubse=read_json(maintenance.STAGE/'journal.json')['currentProcess']
        proc['ubse']={'pid':ubse['pid'],'ticks':ubse['ticks']}
        schema=dict(self.state['engineSchema'])
        if schema.get('attested'):
            try:
                info=Path(schema['executable']).stat()
                need([info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns]==schema['fileIdentity']
                     and measure.process_identity(ubse['pid'])==ubse['ticks'],'Engine identity changed')
            except (OSError,RuntimeError) as error:schema.update(attested=False,reason=str(error))
        mapping=measure.region_evidence(proc['view']['pid'],proc['view']['ticks'],root_journal['volume']['segments'],
                                       schema.get('attested'),self.work/'mapping-evidence')
        sample=measure.sample(proc)
        sample.update(localRead=reply,ordinaryFilesAfterDax={
            'baseline':measure.residency(self.plan['baselineFile'],8*MIB)},ordinaryFilesBeforeDax=ordinary,
            sdkCoverage={'rows':self.state['owner']['ownerJournal'].get(
                'objects' if self.node=='node-a' else 'imports',[]),
                'meaning':'SDK mapped coverage; not physical allocation increment'},
            mappingEvidence=mapping,baseline=self.state['baseline'],
            engineSchema=schema,
            physicalSharingAccepted=False)
        if self.node=='node-a':
            sample['ordinaryFilesAfterDax']['container']=measure.residency(self.prep/'host-dax-test.ext4',64*MIB)
        put(self.work/'candidate-sample.json',sample)
        return sample

    def view_action(self,action):
        result=command(self.python('aenv_ub_provider.host_pmem_cli',action,'--config',self.view_config,
                       '--expected-config-sha256',self.state['viewConfigSha256']),timeout=90,check=False)
        need(result.returncode==0,'Root view action did not confirm completion: '+result.stderr[-1800:])
        return json.loads(result.stdout)

    def verify_again(self):
        reply=self.view_action('verify')
        need(reply.get('state')=='local_read_verified','DAX re-read was not verified')
        return {'passed':True,'result':reply}

    def release_view(self):
        if self.state.get('viewLaunchAttempted') is not True:
            # A failure before submitting systemd-run cannot have acquired a
            # local view. Do not apply this to an unacknowledged launch.
            need(unit(self.view_unit)['LoadState']=='not-found' and not (self.work/'view').exists(),
                 'Unexpected view state; cannot certify a never-started view')
            owner=self.state['owner'];publication=owner['publication'];replica=publication['replicas'][0]
            source={**replica['identity'],'socket':str(self.prep/'provider/data.sock')}
            receipt={'version':1,'scope':'local-host-pmem','state':'released',
                'publication':{'ownerId':publication['ownerId'],
                    'manifestSha256':workflow.manifest_identity(publication),'objectName':replica['objectName']},
                'source':source,'bootId':self.plan['maintenance']['bootId'],'ownerUid':1204,
                'ownerPid':owner['process']['pid'],'ownerStartTicks':owner['process']['ticks'],
                'volumeCreated':False,'creationOutcome':'not_attempted','volumeUuid':None,'volumeId':None,
                'mountAbsent':True,'localVolumeAbsent':True,'sharedBackingReleaseAuthorized':False}
            if self.release_file.exists():need(read_json(self.release_file)==receipt,'Existing retirement receipt differs')
            else:put(self.release_file,receipt,shared=True)
            return receipt
        reply=self.view_action('retire')
        need(reply.get('state') in ('local_resources_released','released'),'Local view retirement not confirmed')
        helper=read_json(self.work/'view/host-pmem-session.json')['helper']
        self.wait_stopped(self.view_unit,{'pid':helper['pid'],'ticks':helper['startTicks']})
        return read_json(self.release_file)

    def release_sdk(self,peer_receipt):
        journal=read_json(self.prep/'provider/owner.json')
        if journal.get('state')!='released':
            status=unit(self.sdk_unit);expected=self.state['owner']['process']
            need(status['ActiveState']=='active' and int(status['MainPID'])==expected['pid']
                 and measure.process_identity(expected['pid'])==expected['ticks'],'SDK owner identity changed')
            argv=['retire',str(self.prep/'provider')]
            if peer_receipt is not None:
                peer_file=BASE/'receipts'/(self.node+'-peer.json');put(peer_file,peer_receipt,shared=True)
                argv+=['--peer-receipt',str(peer_file)]
            result=command(self.python('aenv_ub_provider',*argv),timeout=180,owner=True,check=False)
            need(result.returncode==0,'SDK retirement not confirmed; preserve object and module')
            journal=read_json(self.prep/'provider/owner.json')
        need(journal.get('state')=='released','SDK owner did not record release')
        need(journal.get('finalize_acknowledged') is True,'SDK finalization is not acknowledged')
        self.wait_stopped(self.sdk_unit,self.state['owner']['process'])
        if self.node=='node-b':return read_json(self.prep/'provider/release.json')
        need(all(row.get('creation_confirmed') and row.get('delete_acknowledged') for row in journal.get('objects',[]))
             and len(journal.get('objects',[]))==1,'Global object deletion not confirmed')
        return {'state':'released','ownerId':self.state['owner']['publication']['ownerId'],
                'manifestSha256':workflow.manifest_identity(self.state['owner']['publication']),
                'globalObjectDeleteAcknowledged':True}

    def wait_stopped(self,name,expected):
        deadline=time.monotonic()+30
        while time.monotonic()<deadline:
            status=unit(name)
            if status['LoadState']=='not-found' or (status['ActiveState'] in ('inactive','failed') and status['MainPID']=='0'):
                self.state.setdefault('workerExit',{})[name]=status;self.save(self.state)
                return
            if expected is not None:
                need(int(status['MainPID'])==expected['pid']
                     and measure.process_identity(expected['pid'])==expected['ticks'],'Owned process identity changed')
            time.sleep(0.25)
        raise TimeoutError('Released worker has not exited; no signal or force cleanup sent')

    def check_no_sdk_attempt(self):
        need(not (self.prep/'provider').exists(),'SDK state exists; cannot claim no attempt')
        for name in (self.sdk_unit,self.view_unit):
            need(unit(name)['LoadState']=='not-found','Owned unit exists; cannot issue no-SDK receipt')

    def restore_module(self):
        # Module helper independently checks exact identity, no regions/holders,
        # and zero references AFTER the known UBSE stop. It never forces unload.
        module=Path('/sys/module/obmm')
        if module.exists() and maintenance.read(module/'srcversion')==maintenance.OLD_SRC:
            maintenance.check_module(maintenance.OLD_SRC,maintenance.PARAMS)
            maintenance.pinned_bytes(maintenance.OLD_FILE,maintenance.OLD_SHA)
            current=maintenance.service()
            if current['ActiveState']=='active':
                return {'phase':'original_loaded_ubse_active','action':'verified_already_original_no_action',
                        'originalModuleSrcversion':maintenance.OLD_SRC,'originalModuleSha256':maintenance.OLD_SHA,
                        'originalParameters':dict(maintenance.PARAMS),
                        'restoredProcess':maintenance.process(int(current['MainPID'])),
                        'taintAfterRestore':maintenance.read('/proc/sys/kernel/tainted')}
        before=list(sys.argv);output=io.StringIO()
        try:
            sys.argv=['maintenance','restore','--approval',APPROVAL]
            with contextlib.redirect_stdout(output):rc=maintenance.main()
        finally:
            sys.argv=before
            (self.work/'maintenance-restore.log').write_text(output.getvalue())
        need(rc==0,'Original module restoration stopped; preserve recovery state')
        result=read_json(maintenance.STAGE/'journal.json')
        need(result['phase']=='original_loaded_ubse_active','Original module restoration unconfirmed')
        result['taintAfterRestore']=maintenance.read('/proc/sys/kernel/tainted')
        result['originalModuleSrcversion']=maintenance.OLD_SRC
        result['originalModuleSha256']=maintenance.OLD_SHA
        return result


def report(state,peer_token):
    result={'node':state['node'],'phase':state['phase'],'coreCommit':state['coreCommit'],
            'scope':'small Host pmem test, not a Guest/rootfs workload benchmark',
            'localOriginalRestored':state['phase']=='original_restored','peerOriginalRestored':None,
            'netSavingsBytes':None,'twoNodeHostGatePassed':False,'Guest_created':False}
    if peer_token is not None:
        flow=workflow.Workflow(state,lambda _:None,None)
        peer=flow.peer(peer_token,'original_restored')
        expected=(state.get('peerEvidence') or state.get('restoreEvidence') or {}).get('epoch')
        need(peer['epoch']==expected and peer['restoration']['phase']=='original_loaded_ubse_active',
             'Peer restoration does not match this experiment epoch')
        need(peer['restoration']['originalModuleSrcversion']==maintenance.OLD_SRC
             and peer['restoration']['originalModuleSha256']==maintenance.OLD_SHA
             and peer['restoration']['originalParameters']==maintenance.PARAMS,'Peer original module identity differs')
        result['peerOriginalRestored']=True
    if state['node']=='node-a':
        peer_release=state.get('peerRelease',{})
        if state.get('sample') and peer_release.get('dataReadPassed') and peer_release.get('dataEvidence'):
            comparison=measure.compare_samples(state['sample'],peer_release['dataEvidence'],64*MIB)
            result['comparison']=comparison
            result['peerExitRead']=state.get('peerExitRead')
            result['twoNodeHostGatePassed']=(result['localOriginalRestored'] and result['peerOriginalRestored'] is True
                and comparison['mappingEvidence']['matched'] is True
                and state.get('peerExitRead',{}).get('passed') is True
                and all(row['localReadPassed'] and row['candidateDataBlockCacheBytes']==0
                        for row in comparison['nodes']))
        else:result['comparison']=None;result['reason']='No complete two-node data evidence; do not infer savings'
    return result


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode',choices=('plan','activate','start','release','restore','abort-no-sdk','request-cancel','cancel-import','status','report'))
    parser.add_argument('--peer-token');parser.add_argument('--approval')
    args=parser.parse_args()
    node=next((key for key,value in plans.items() if value['maintenance']['node']==platform.node()),None)
    need(node is not None,'Unknown target node')
    if args.mode=='plan':
        print(json.dumps({'node':node,'coreCommit':CORE_COMMIT,'candidateSha256':CANDIDATE_SHA,
            'logicalUbBytes':64*MIB,'coverageGuardBytes':256*MIB,'physicalHardQuota':False,
            'moduleChangesRequireSeparateApproval':True,'SDK_called':False,'Guest_created':False,
            'sequence':'both activate; A start; B start; B release; A release; then both restore'},indent=2));return
    need(os.getuid()==os.geteuid()==0,'Expected root')
    if args.mode in ('status','report'):
        state=read_json(BASE/node/'workflow.json')
        value=state if args.mode=='status' else report(state,args.peer_token)
        print(json.dumps(value,indent=2))
        if args.mode=='status':
            # Recover lost terminal output from durable state without any
            # repeated module/SDK action. Never synthesize a future phase.
            keys={'module_ready':'moduleReady','data_ready':'dataReady','released':'releaseToken',
                  'reader_cancelled':'releaseToken','aborted_no_sdk':'abortToken',
                  'cancel_request_issued':'cancelRequest','original_restored':'restorationToken'}
            key=keys.get(state['phase'])
            if key and key in state:
                print('BEGIN_HOST_PMEM_RELAY_TOKEN');print(workflow.encode(state[key]));print('END_HOST_PMEM_RELAY_TOKEN')
        else:put(BASE/node/'final-report.json',value)
        return
    need(platform.release()==KERNEL,'Exact kernel required')
    need(Path('/proc/sys/kernel/random/boot_id').read_text().strip()==plans[node]['maintenance']['bootId'],'Boot changed')
    need(args.approval==APPROVAL,'Separate concrete A/B module and bounded UB test approval is required')
    parent=BASE.parent;info=parent.stat()
    need(parent.resolve(strict=True)==parent and info.st_uid==0 and not info.st_mode&0o022,'Unsafe staging parent')
    owned_dir(BASE,0o755);owned_dir(BASE/'configs',0o755);owned_dir(BASE/'receipts',0o755);owned_dir(BASE/node,0o700)
    import fcntl
    lock=os.open(BASE/node/'operation.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
    try:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        journal=BASE/node/'workflow.json'
        state=read_json(journal) if journal.exists() else {'version':1,'node':node,'phase':'prepared',
            'epoch':uuid.uuid4().hex,'experiment':'host-pmem-'+IMAGE_SHA[:16],'imageSha256':IMAGE_SHA,'coreCommit':CORE_COMMIT}
        need(state['node']==node and state['coreCommit']==CORE_COMMIT and state['imageSha256']==IMAGE_SHA,'Existing experiment differs')
        ops=Operations(node,state);flow=workflow.Workflow(state,ops.save,ops);ops.save(state)
        try:
            if args.mode=='activate':result=flow.activate()
            elif args.mode=='start':result=flow.start(args.peer_token)
            elif args.mode=='release':result=flow.release(args.peer_token)
            elif args.mode=='restore':result=flow.restore(args.peer_token)
            elif args.mode=='abort-no-sdk':result=flow.abort_no_sdk()
            elif args.mode=='request-cancel':result=flow.request_cancel()
            else:result=flow.cancel_import(args.peer_token)
        except BaseException as error:
            state['lastFailure']={'phase':state['phase'],'reason':str(error)};ops.save(state)
            raise
        if isinstance(result,str):
            (BASE/node/(args.mode+'.token')).write_text(result+'\n')
            print('BEGIN_HOST_PMEM_RELAY_TOKEN');print(result);print('END_HOST_PMEM_RELAY_TOKEN')
        else:print(json.dumps(result,indent=2))
        print(json.dumps({'status':state['phase'],'node':node,'journal':str(journal),'twoNodeAccepted':False,
                          'netSavingsBytes':None,'Guest_created':False}),flush=True)
    finally:os.close(lock)


if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'status':'HOST_PMEM_STOPPED_PRESERVE_STATE','reason':str(error),
                          'automaticRollbackExecuted':False}),flush=True)
        raise SystemExit(1)
